/** @type {import('jest').Config} */
module.exports = {
  preset: 'ts-jest',
  testEnvironment: 'node',
  roots: ['<rootDir>/test'],
  testMatch: ['**/*.test.ts'],
  transform: {
    '^.+\\.ts$': 'ts-jest',
  },
};

import matter from 'gray-matter';
import { marked } from 'marked';

export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[] | string;
}

export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  html: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

const FRONTMATTER_DELIMITER = /^\uFEFF?---\s*\r?\n([\s\S]*?)\r?\n---\s*(?:\r?\n|$)/;

/**
 * Parse YAML frontmatter from a raw markdown file and return the metadata
 * plus the stripped markdown body. The frontmatter block is stripped here so
 * that it is never passed to the markdown renderer.
 */
export function parseFrontmatter(raw: string): { frontmatter: Frontmatter; content: string } {
  const normalized = raw.replace(/^\uFEFF/, '');
  let parsed: { data: Record<string, unknown>; content: string };

  if (FRONTMATTER_DELIMITER.test(normalized)) {
    parsed = matter(normalized);
  } else {
    parsed = { data: {}, content: normalized };
  }

  return {
    frontmatter: parsed.data as Frontmatter,
    content: parsed.content,
  };
}

/** Normalize a tags value (string or array) into a string array. */
export function normalizeTags(tags: Frontmatter['tags']): string[] {
  if (tags == null) {
    return [];
  }
  if (Array.isArray(tags)) {
    return tags.map((t) => String(t).trim()).filter((t) => t.length > 0);
  }
  return String(tags)
    .split(',')
    .map((t) => t.trim())
    .filter((t) => t.length > 0);
}

/** Convert a markdown body to HTML. */
export function markdownToHtml(markdown: string): string {
  return marked.parse(markdown, { async: false }) as string;
}

import { Page } from './ssg';

export function escapeHtml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function pageMeta(page: Page): string {
  const parts: string[] = [];
  if (page.date) {
    parts.push(`<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>`);
  }
  if (page.tags.length > 0) {
    parts.push(
      `<span class="tags">${page.tags.map((t) => `<span class="tag">${escapeHtml(t)}</span>`).join('')}</span>`
    );
  }
  return parts.length > 0 ? `<p class="meta">${parts.join(' ')}</p>` : '';
}

function baseLayout(title: string, body: string): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(title)}</title>
</head>
<body>
  <header>
    <a href="index.html">Home</a>
  </header>
  <main>
${body}
  </main>
</body>
</html>
`;
}

export function renderPage(page: Page): string {
  const body = `    <article>
      <h1>${escapeHtml(page.title)}</h1>
${pageMeta(page)}
${page.html}
    </article>
`;
  return baseLayout(page.title, body);
}

export function renderIndex(pages: Page[]): string {
  const listItems = pages
    .map((page) => {
      const meta = page.date ? ` <small>${escapeHtml(page.date)}</small>` : '';
      return `      <li><a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.title)}</a>${meta}</li>`;
    })
    .join('\n');

  const body = `    <h1>All Posts</h1>
    <ul>
${listItems || '      <li>No posts found.</li>'}
    </ul>
`;
  return baseLayout('Home', body);
}

import * as fs from 'fs';
import * as path from 'path';
import { BuildOptions, Page, markdownToHtml, normalizeTags, parseFrontmatter } from './ssg';
import { renderIndex, renderPage } from './templates';

function slugFromFilename(filename: string): string {
  const ext = path.extname(filename);
  return filename.slice(0, filename.length - ext.length);
}

/** Recursively collect all .md file paths under a directory, sorted by path. */
export function findMarkdownFiles(contentDir: string): string[] {
  const results: string[] = [];

  function walk(dir: string): void {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    entries.sort((a, b) => a.name.localeCompare(b.name));
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
      } else if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
        results.push(full);
      }
    }
  }

  if (fs.existsSync(contentDir)) {
    walk(contentDir);
  }
  return results;
}

export function loadPages(contentDir: string): Page[] {
  const files = findMarkdownFiles(contentDir);
  const pages: Page[] = [];

  for (const file of files) {
    const raw = fs.readFileSync(file, 'utf8');
    const { frontmatter, content } = parseFrontmatter(raw);
    const html = markdownToHtml(content);
    pages.push({
      slug: slugFromFilename(path.basename(file)),
      title: frontmatter.title || slugFromFilename(path.basename(file)),
      date: frontmatter.date,
      tags: normalizeTags(frontmatter.tags),
      html,
    });
  }

  return pages.sort((a, b) => {
    const ad = a.date || '';
    const bd = b.date || '';
    if (ad === bd) {
      return a.title.localeCompare(b.title);
    }
    return ad < bd ? 1 : -1;
  });
}

export interface BuildResult {
  outputDir: string;
  writtenFiles: string[];
}

export function build(options: BuildOptions): BuildResult {
  const { contentDir, outputDir } = options;
  const pages = loadPages(contentDir);

  fs.mkdirSync(outputDir, { recursive: true });

  const writtenFiles: string[] = [];

  const indexHtml = renderIndex(pages);
  const indexPath = path.join(outputDir, 'index.html');
  fs.writeFileSync(indexPath, indexHtml, 'utf8');
  writtenFiles.push(indexPath);

  for (const page of pages) {
    const pageHtml = renderPage(page);
    const pagePath = path.join(outputDir, `${page.slug}.html`);
    fs.writeFileSync(pagePath, pageHtml, 'utf8');
    writtenFiles.push(pagePath);
  }

  return { outputDir, writtenFiles };
}

import { build } from './build';

interface ParsedArgs {
  command: string;
  content: string;
  output: string;
}

export function parseArgs(argv: string[]): ParsedArgs {
  const args = argv.slice(2);
  const command = args.find((a) => !a.startsWith('-')) || 'build';
  let content = './content';
  let output = './dist';

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--content' || arg === '-c') {
      content = args[i + 1] ?? content;
      i++;
    } else if (arg.startsWith('--content=')) {
      content = arg.slice('--content='.length);
    } else if (arg === '--output' || arg === '-o') {
      output = args[i + 1] ?? output;
      i++;
    } else if (arg.startsWith('--output=')) {
      output = arg.slice('--output='.length);
    }
  }

  return { command, content, output };
}

export function run(argv: string[]): void {
  const { command, content, output } = parseArgs(argv);

  if (command === 'build') {
    const result = build({ contentDir: content, outputDir: output });
    console.log(`Built ${result.writtenFiles.length} files into ${result.outputDir}`);
    return;
  }

  console.error(`Unknown command: ${command}`);
  console.error('Usage: ssg build [--content <dir>] [--output <dir>]');
  process.exitCode = 1;
}

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { build, loadPages } from '../src/build';
import { markdownToHtml, normalizeTags, parseFrontmatter } from '../src/ssg';

function makeTempDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-test-'));
}

describe('parseFrontmatter', () => {
  it('extracts title, date and tags and strips the frontmatter block', () => {
    const raw = `---
title: Hello World
date: 2024-01-01
tags:
  - typescript
  - ssg
---
# Body

Some content.
`;
    const { frontmatter, content } = parseFrontmatter(raw);
    expect(frontmatter.title).toBe('Hello World');
    expect(frontmatter.date).toBe('2024-01-01');
    expect(frontmatter.tags).toEqual(['typescript', 'ssg']);
    expect(content).not.toContain('---');
    expect(content).toContain('# Body');
  });

  it('handles files without frontmatter', () => {
    const raw = '# Just a heading\n\nText.';
    const { frontmatter, content } = parseFrontmatter(raw);
    expect(frontmatter).toEqual({});
    expect(content).toBe(raw);
  });

  it('handles a leading BOM', () => {
    const raw = '\uFEFF---\ntitle: BOM\n---\n\nbody';
    const { frontmatter, content } = parseFrontmatter(raw);
    expect(frontmatter.title).toBe('BOM');
    expect(content.trim()).toBe('body');
  });
});

describe('normalizeTags', () => {
  it('returns an empty array for undefined', () => {
    expect(normalizeTags(undefined)).toEqual([]);
  });

  it('splits comma-separated strings', () => {
    expect(normalizeTags('a, b, c')).toEqual(['a', 'b', 'c']);
  });

  it('accepts arrays', () => {
    expect(normalizeTags(['x', 'y'])).toEqual(['x', 'y']);
  });
});

describe('markdownToHtml', () => {
  it('renders markdown to html', () => {
    const html = markdownToHtml('# Title\n\n**bold**');
    expect(html).toContain('<h1>');
    expect(html).toContain('<strong>bold</strong>');
  });

  it('does not render a frontmatter block as literal HTML', () => {
    const html = markdownToHtml('# Body');
    expect(html).not.toContain('---');
  });
});

describe('build', () => {
  it('generates index.html and one page per markdown file', () => {
    const contentDir = makeTempDir();
    const outputDir = makeTempDir();

    fs.writeFileSync(
      path.join(contentDir, 'first-post.md'),
      `---
title: First Post
date: 2024-02-01
tags: [one]
---
# First

Hello first.
`
    );
    fs.writeFileSync(
      path.join(contentDir, 'second-post.md'),
      `---
title: Second Post
date: 2024-01-01
---
# Second

Hello second.
`
    );

    const result = build({ contentDir, outputDir });

    expect(result.writtenFiles).toHaveLength(3);

    const indexHtml = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf8');
    expect(indexHtml).toContain('First Post');
    expect(indexHtml).toContain('Second Post');
    expect(indexHtml).toContain('first-post.html');
    expect(indexHtml).toContain('second-post.html');

    const firstHtml = fs.readFileSync(path.join(outputDir, 'first-post.html'), 'utf8');
    expect(firstHtml).toContain('<h1>First Post</h1>');
    expect(firstHtml).toContain('<h1>First</h1>');
    expect(firstHtml).toContain('2024-02-01');

    const secondHtml = fs.readFileSync(path.join(outputDir, 'second-post.html'), 'utf8');
    expect(secondHtml).toContain('<h1>Second Post</h1>');
  });

  it('orders pages by date descending in the index', () => {
    const contentDir = makeTempDir();
    const outputDir = makeTempDir();

    fs.writeFileSync(
      path.join(contentDir, 'a.md'),
      `---\ntitle: A\ndate: 2024-01-01\n---\nA`
    );
    fs.writeFileSync(
      path.join(contentDir, 'b.md'),
      `---\ntitle: B\ndate: 2024-03-01\n---\nB`
    );

    build({ contentDir, outputDir });

    const indexHtml = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf8');
    expect(indexHtml.indexOf('b.html')).toBeLessThan(indexHtml.indexOf('a.html'));
  });

  it('reads markdown recursively from subdirectories', () => {
    const contentDir = makeTempDir();
    const outputDir = makeTempDir();

    fs.mkdirSync(path.join(contentDir, 'nested'));
    fs.writeFileSync(
      path.join(contentDir, 'nested', 'deep.md'),
      `---\ntitle: Deep\n---\nDeep content`
    );

    build({ contentDir, outputDir });

    expect(fs.existsSync(path.join(outputDir, 'deep.html'))).toBe(true);
  });

  it('loads pages with defaults when frontmatter is missing', () => {
    const contentDir = makeTempDir();
    fs.writeFileSync(path.join(contentDir, 'plain.md'), '# Plain\n\nNo frontmatter.');

    const pages = loadPages(contentDir);
    expect(pages).toHaveLength(1);
    expect(pages[0].title).toBe('plain');
    expect(pages[0].tags).toEqual([]);
    expect(pages[0].html).toContain('<h1>');
  });

  it('builds into a fresh output directory', () => {
    const contentDir = makeTempDir();
    const outputDir = path.join(makeTempDir(), 'nested', 'out');

    fs.writeFileSync(path.join(contentDir, 'x.md'), `---\ntitle: X\n---\nX`);
    build({ contentDir, outputDir });

    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
  });
});

